// Actions-only user read controls: no real native SDK/service invocation.
#[tokio::test]
async fn im_user_read_routes_require_auth_strict_body_and_no_caller_index_uid_token_or_cached_grant(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let base="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef";
    for(method,path)in[(reqwest::Method::GET,format!("{base}/im-user-reads")),(reqwest::Method::POST,format!("{base}/im-messages/1/mark-read"))]{let(status,_,body)=account_request(&served,method,&path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);}
    let cookie=authenticate(&served).await;for body in [serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"consent":true,"index":"7"}),serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"consent":true,"token":"fixture-must-not-echo"}),serde_json::json!({"expected_revision":1,"nonce":"bad","consent":true})]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/im-messages/1/mark-read"),Some(body),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
    for id in ["0","-1","01","9223372036854775808"]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/im-messages/{id}/mark-read"),Some(serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());
}
#[tokio::test]
async fn im_user_read_installation_is_separate_and_cannot_start_sdk_or_get_user_consent_from_a_status(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let mut good=im_runtime_config_json(&cert.root);good["profile"]["im_user_read"]=serde_json::json!({"mark_read":true});assert!(good["profile"].get("im_receipts").is_none());
    for setting in [serde_json::json!({"mark_read":false}),serde_json::json!({"mark_read":true,"uid":"fixture-must-not-echo"})]{let mut bad=good.clone();bad["profile"]["im_user_read"]=setting;let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":bad})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
    let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":good})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);no_store(&headers);let line=created_line(&body);let view=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(view.phase,"stopped");assert!(!view.incoming_message_ready&&!view.incoming_call_ready&&!view.outbound_authorized&&!view.io_cleanup_required);let path=format!("/api/non-3gpp/accounts/{line}/im-messages/1/mark-read");
    let(status,headers,body)=account_request(&served,reqwest::Method::POST,&path,Some(serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"consent":false})),Some(&cookie)).await;assert_eq!(status,StatusCode::FORBIDDEN);no_store(&headers);no_secrets(&body);
    let(status,headers,body)=account_request(&served,reqwest::Method::POST,&path,Some(serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::SERVICE_UNAVAILABLE);no_store(&headers);no_secrets(&body);
}
#[tokio::test]
async fn im_user_read_metadata_is_no_store_full_index_and_private_unknown_does_not_authorize_any_write(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":im_runtime_config_json(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);
    state.app.database.with_conn(|c|c.execute("INSERT INTO app_voice_im_user_reads(line_id,revision,identity_key,box_id,message_id,target_index,fingerprint,user_nonce,epoch_ms,run_nonce,scope_epoch,state,request_id,updated_at) VALUES(?1,1,?2,?3,1,?4,?5,?6,0,?7,'private-scope',0,9,'2026-01-01T00:00:00Z')",rusqlite::params![line,vec![7u8;32],b"P2P/1_2".as_slice(),i64::MAX,vec![8u8;32],"a".repeat(32),"b".repeat(32)]).map_err(|_|"fixture")).unwrap();let path=format!("/api/non-3gpp/accounts/{line}/im-user-reads");
    for q in ["?limit=0","?limit=129","?limit=1&uid=fixture-must-not-echo"]{let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{path}{q}"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&path,None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);let value:serde_json::Value=serde_json::from_str(&body).unwrap();assert_eq!(value["data"][0]["target_index"],"9223372036854775807");assert_eq!(value["data"][0]["state"],"uncertain");for p in ["identity_key","P2P/1_2","private-scope","user_nonce","request_id","fingerprint","run_nonce"]{assert!(!body.contains(p));}assert!(state.app.app_accounts.messages(&line,16).unwrap().is_empty());
}
